    // Nombre propio primero: «nube» → Camisa Denim Nube + referencias parecidas (MSJ Search, search-engine.js).
    if(window.MSJSearch&&!/disponible/.test(text)){const found=window.MSJSearch.lookup(question,visibleProducts());const generic=mishiCategoryWords.some(([pattern])=>pattern.test(text))&&found.strong.length>3;if(found.top&&!generic&&found.strong.length<=6){const main=found.strong.slice(0,6);window.MSJSearch.log(question,found.hits.length,'mishi');return {text:main.length===1?`✨ Encontré «${main[0].name}». También te dejo referencias que combinan con tu búsqueda:`:`✨ Encontré ${main.length} productos con «${question.trim()}» en el nombre:`,products:main.map(product=>product.slug),references:main.length<=2?found.references.slice(0,4).map(product=>product.slug):[],link:['Ver todos los resultados',`tienda.html?q=${encodeURIComponent(question.trim())}`]}}}
    const availability=question.match(/disponible\s+(.+?)\??$/i);if(availability){const product=findProduct(normalize(availability[1]))||state.products.find(item=>normalize(availability[1]).includes(normalize(item.name)));if(product)return {text:canBuy(product)?`¡Sí! ${product.name} está disponible. Elige tu talla y agrégalo a tu bolsa.`:`${product.name} se está incorporando a nuestro stock en línea. ${whatsappNumber?'Escríbenos por WhatsApp y te avisamos apenas esté lista.':'Déjanos tus datos en “Hablar con el equipo” y te avisamos.'}`,products:[product.slug],link:whatsappNumber?['Consultar por WhatsApp',whatsappLink(`Hola MSJ, ¿está disponible ${product.name}?`)]:null}}
    if(/outfit|look|combina|conjunto para|que me pongo|vestirme/.test(text))return mishiOutfit(text);
