    const notes=mishiNotes.filter(([pattern])=>pattern.test(text)).flatMap(([,words])=>words);if(notes.length&&(categories.includes('perfumes')||/perfume|fragancia|aroma/.test(text))){const scored=products.filter(product=>notes.some(word=>normalize(product.description).includes(word)));if(scored.length){products=scored;filters.push('según sus notas')}}
    const collection=(mishiCollections.find(([pattern])=>pattern.test(text))||[])[1];if(collection&&!categories.includes('perfumes')){const inCollection=products.filter(product=>product.collections.includes(collection));if(inCollection.length)products=inCollection}
    const gift=/regalo|regalar|obsequio|detalle/.test(text);if(gift&&!categories.length)products=products.filter(product=>['perfumes','joyeria','relojes','bolsos','lentes','cinturones','gorras','polos'].includes(product.category_slug));
