    const offers=/oferta|descuento|rebaja|barato|sale|promo/.test(text);if(offers)products=products.filter(product=>Number(product.discount_percent)>0);
    const fresh=/nuevo|novedad|ultimo|recien/.test(text);if(fresh)products=products.filter(product=>product.is_new);
    const understood=audience||categories.length||notes.length||collection||gift||limit||offers||fresh;
    if(!understood&&window.MSJSearch){const found=window.MSJSearch.lookup(question,visibleProducts());window.MSJSearch.log(question,found.hits.length,'mishi');if(found.hits.length){const ordered=mishiBuyable(found.hits.map(hit=>hit.product));if(ordered.length)return {text:`🔎 Esto es lo más cercano a «${question.trim()}»:`,products:ordered.slice(0,6).map(product=>product.slug),references:found.top?found.references.slice(0,3).map(product=>product.slug):[],link:['Ver todos los resultados',`tienda.html?q=${encodeURIComponent(question.trim())}`]}}if(found.didYouMean)return {text:`No encontré «${question.trim()}». ¿Quisiste decir «${found.didYouMean}»?`,ask:[`Sí, buscar «${found.didYouMean}»`,found.didYouMean],chips:['🎄 Regalos de Navidad','Promos de hoy']}}
    if(!understood){const words=text.split(/\s+/).filter(word=>word.length>3);products=words.length?visibleProducts().filter(product=>{const haystack=normalize([product.name,product.description,product.category_name,...(product.colors||[])].join(' '));return words.some(word=>haystack.includes(word))}):[];if(!products.length)return {text:'Mmm, no estoy segura de qué buscas 🐾. Puedo encontrarte prendas, armar outfits, recomendar perfumes y regalos, o ayudarte con envíos, pagos y cambios. Toca una idea o escríbeme algo como «casaca negra para hombre».',chips:['🎄 Regalos de Navidad','Recomiéndame un outfit','Perfume dulce para ella']}}
    products=mishiBuyable(products);products=offers?[...products].sort((a,b)=>Number(b.discount_percent||0)-Number(a.discount_percent||0)):mishiRank(products);if(window.MSJSearch&&!offers){/* Lo que coincide con toda la frase («negra», «cuero»…) va primero; el resto mantiene el orden de M.I.S.H.I. */const ranked=window.MSJSearch.rank(products,question);products=[...ranked,...products.filter(product=>!ranked.includes(product))]}
