  function mishiAsk(question){const text=String(question||'').trim().slice(0,300);if(!text)return;mishiSay({role:'user',text});const typing=mishiTyping();const local=mishiAnswer(text);const ai=window.MSJMishiAI;if(ai?.enabled()&&ai.shouldUse(text,local)){ai.ask(text,local).then(answer=>{typing.remove();mishiSay({role:'bot',...(answer||local)})});return}setTimeout(()=>{typing.remove();mishiSay({role:'bot',...local})},vipLevel()?.key==='black'?140:420)}
  function mishiOpen(question){const panel=$('#mishi-panel');panel.hidden=false;requestAnimationFrame(()=>panel.classList.add('open'));$('#mishi-open').setAttribute('aria-expanded','true');document.body.classList.add('mishi-active');const level=vipLevel();if(!$('#mishi-messages').children.length){const history=mishiHistory();if(history.length)history.forEach(mishiRender);else mishiSay({role:'bot',text:mishiGreeting()})}let greeted='';try{greeted=sessionStorage.getItem('msj-mishi-vip-greeted')||''}catch{}if(level&&greeted!==level.key){if(mishiHistory().length>1)mishiSay({role:'bot',text:mishiGreeting()});try{sessionStorage.setItem('msj-mishi-vip-greeted',level.key)}catch{}}loadZones();if(question)mishiAsk(question);else $('#mishi-input').focus()}
