  function mishiAddFromChat(product,button){const variants=productVariants(product);if(variants.length===1){addVariant(product,variants[0]);mishiSay({role:'bot',text:`Listo 🛍️ Agregué ${product.name} a tu bolsa.`});return}const colors=[...new Set(variants.map(variant=>variant.color))];const options=[...new Map(variants.filter(variant=>variant.color===colors[0]).map(variant=>[variant.size,variant])).values()];const actions=button.closest('.mishi-card-actions');actions.innerHTML=`<span class="mishi-size-label">${product.department==='perfumes'?'Tamaño':'Talla'}:</span>${options.map((variant,index)=>`<button class="size" data-mishi-size="${index}">${escapeHtml(variant.size)}</button>`).join('')}`;actions.msjProduct=product;actions.msjOptions=options}

